using AlshrouqSchool.Domain.Contracts; using AlshrouqSchool.Domain.Entities.MediaAndContentModule; using AlshrouqSchool.Shared.DTOs.Gallery.PostMedia; using AutoMapper; using MediatR;
namespace AlshrouqSchool.Application.Features.Gallery.Commands.PostMedia;
public sealed record AttachMediaToPostCommand(AttachMediaToPostDto Dto):IRequest<PostMediaDto>; public sealed record DetachMediaFromPostCommand(DetachMediaFromPostDto Dto):IRequest<bool>; public sealed record ReorderPostMediaCommand(ReorderPostMediaDto Dto):IRequest<bool>;
public sealed class AttachMediaToPostCommandHandler(IUnitOfWork unitOfWork,IMapper mapper):IRequestHandler<AttachMediaToPostCommand,PostMediaDto>{public async Task<PostMediaDto> Handle(AttachMediaToPostCommand r,CancellationToken ct){var posts=unitOfWork.GetRepository<Post,int>();var media=unitOfWork.GetRepository<Media,int>();var links=unitOfWork.GetRepository<PostMedia,int>();var post=await posts.GetByIdAsync(r.Dto.PostId);var item=await media.GetByIdAsync(r.Dto.MediaId);if(post is null||post.IsDeleted)throw new KeyNotFoundException("Post was not found.");if(item is null||item.IsDeleted)throw new KeyNotFoundException("Media was not found.");if((await links.GetAllAsync()).Any(x=>x.PostId==r.Dto.PostId&&x.MediaId==r.Dto.MediaId))throw new InvalidOperationException("Media is already attached to this post.");var entity=new PostMedia{PostId=r.Dto.PostId,MediaId=r.Dto.MediaId,MediaRole=r.Dto.MediaRole,DisplayOrder=r.Dto.DisplayOrder,Post=post,Media=item};await links.AddAsync(entity);await unitOfWork.SAveChangesAsync(ct);return mapper.Map<PostMediaDto>(entity);}}
public sealed class DetachMediaFromPostCommandHandler(IUnitOfWork unitOfWork):IRequestHandler<DetachMediaFromPostCommand,bool>{public async Task<bool> Handle(DetachMediaFromPostCommand r,CancellationToken ct){var repo=unitOfWork.GetRepository<PostMedia,int>();var entity=(await repo.GetAllAsync()).FirstOrDefault(x=>x.PostId==r.Dto.PostId&&x.MediaId==r.Dto.MediaId);if(entity is null)return false;repo.Delete(entity);await unitOfWork.SAveChangesAsync(ct);return true;}}
public sealed class ReorderPostMediaCommandHandler(IUnitOfWork unitOfWork):IRequestHandler<ReorderPostMediaCommand,bool>{public async Task<bool> Handle(ReorderPostMediaCommand r,CancellationToken ct){var repo=unitOfWork.GetRepository<PostMedia,int>();var links=(await repo.GetAllAsync()).Where(x=>x.PostId==r.Dto.PostId).ToDictionary(x=>x.Id);if(links.Count==0)return false;if(r.Dto.Items.Any(x=>x.DisplayOrder<0||!links.ContainsKey(x.PostMediaId)))throw new InvalidOperationException("Each reordered media item must belong to the post.");foreach(var item in r.Dto.Items){links[item.PostMediaId].DisplayOrder=item.DisplayOrder;repo.Update(links[item.PostMediaId]);}await unitOfWork.SAveChangesAsync(ct);return true;}}